type Language = 'es' | 'en'
type ThemePreference = 'light' | 'dark' | 'system'
type Expense = { id:string; amount:number; category:string; description:string|null; spent_at:string; source:'web'|'whatsapp'; edited_at:string|null; previous_amount:number|null; previous_category:string|null; previous_description:string|null }
type ProfileSettings = { whatsapp_phone:string|null; monthly_income:number|null; spending_alert:number|null; currency_code:string; monthly_planning_enabled:boolean; onboarding_completed:boolean; theme_preference:ThemePreference; language_preference:Language }
