type UpdateInfo = { available:boolean; currentVersionCode:number; currentVersionName:string; versionCode:number; versionName:string; downloadUrl:string; sha256:string; notes:string }
type AppUpdatePlugin = { check:()=>Promise<UpdateInfo>; downloadAndInstall:(options:{downloadUrl:string;sha256:string})=>Promise<{settingsOpened:boolean}> }

