function defaultCategoryIcon(category:string){return category==='Comida'?'food':category==='Transporte'?'transport':category==='Supermercado'?'shopping':category==='Servicios'?'services':category==='Salud'?'health':category==='Ocio'?'leisure':'tag'}
function CategoryIcon({category,iconKey,size=17}:{category:string,iconKey?:string,size?:number}){const props={size,strokeWidth:1.9};const key=iconKey||defaultCategoryIcon(category);if(key==='food')return <Utensils {...props}/>;if(key==='transport')return <Car {...props}/>;if(key==='shopping')return <ShoppingCart {...props}/>;if(key==='services')return <Zap {...props}/>;if(key==='health')return <HeartPulse {...props}/>;if(key==='leisure')return <Gamepad2 {...props}/>;if(key==='home')return <House {...props}/>;if(key==='education')return <BookOpen {...props}/>;if(key==='pets')return <PawPrint {...props}/>;if(key==='travel')return <Plane {...props}/>;if(key==='gifts')return <Gift {...props}/>;if(key==='clothing')return <Shirt {...props}/>;if(key==='coffee')return <Coffee {...props}/>;if(key==='phone')return <Smartphone {...props}/>;if(key==='internet')return <Wifi {...props}/>;if(key==='fitness')return <Dumbbell {...props}/>;if(key==='baby')return <Baby {...props}/>;if(key==='work')return <BriefcaseBusiness {...props}/>;if(key==='fuel')return <Fuel {...props}/>;if(key==='music')return <Music {...props}/>;if(key==='repairs')return <Wrench {...props}/>;if(key==='money')return <Banknote {...props}/>;return <Tags {...props}/>}
